// 分级：3天内到期=提醒责任人；逾期1-2天=催办；逾期≥3天或累计≥2次=升级老板
const rows = $input.all().map(i => i.json);
const now = Date.now();
const remind = [], urge = [], escalate = [];
for (const r of rows) {
  const days = Math.floor((now - new Date(r.required_date).getTime()) / 86400000);
  if (days > 0) { r.overdue_days = days; (days >= 3 || r.overdue_count >= 2 ? escalate : urge).push(r); }
  else remind.push(r);
}
const fmt = list => list.map(r => `- ${r.task_no} ${r.supplier_name}（${r.task_type}）责任：${r.owner}，要求：${r.required_date}${r.overdue_days ? '，逾期' + r.overdue_days + '天' : ''}`).join('\n');
let text = '### 供应商任务巡检\n';
if (remind.length) text += '**【3天内到期，请跟进】**\n' + fmt(remind) + '\n';
if (urge.length) text += '**【已逾期，请立即催办】**\n' + fmt(urge) + '\n';
return [{ json: { group_text: text, escalate, has_escalate: escalate.length > 0 } }];

const out = [];
for (const it of $input.all()) {
  const ai = it.json.choices?.[0]?.message?.content || it.json.content || '';
  let p;
  try { p = JSON.parse(String(ai).replace(/^```json?|```$/g, '').trim()); }
  catch (e) { throw new Error('AI解析失败，原文转人工：' + String(ai).slice(0, 200)); }
  const src = $('状态回填Webhook').first().json;
  out.push({ json: { ...src, ...p, parse_failed: p.status === null } });
}
return out;
